using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class WorkRelationsTests
{
    static readonly EntityId Lord=new("person:shingen");
    internal static ContractWorld New(){var d=NewGameWorldTests.Setup([NewGameWorldTests.Officer(site:"site:kofu")]);return NewGameWorld.Create(d.World,d.Registered,"created:test",42,NewGameWorld.CompactPersonalAuthority,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy);}
    static void At(WorldSession s,long t)=>NewGameWorldTests.At(s,t);
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
    static WorldSession Report(bool read=true,bool accept=true){var s=new WorldSession(New());Assert.Equal(ResultCode.Accepted,s.Submit(NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:relation"),s.Revision).Code);At(s,1);Open(s);var task=s.DiagnosticSnapshot().Tasks.Last();Assert.Equal(ResultCode.Accepted,s.Assent(task.Id,s.PlayerControl,accept,s.Revision).Code);At(s,8);if(read)Open(s);return s;}
    static EntityId Apply(WorldSession s){var id=new EntityId("request:relation-service");Assert.Equal(ResultCode.Accepted,s.DecideService(new(id,CareerAction.Apply,Principal:Lord),s.PlayerControl,s.Revision).Code);At(s,s.Seconds+2);Open(s);return id;}
    [Fact]public void IssuerKnowsFulfillmentBeforePlayerOpensReply(){var s=Report(false);var w=s.DiagnosticSnapshot();Assert.Single(WorkRelations.Facts(w,Lord,s.PlayerControl));Assert.Empty(WorkRelations.Facts(w,s.PlayerControl,Lord));Assert.Empty(WorkRelations.Known(w));}
    [Fact]public void OpeningMakesOnlyStatedEvidenceVisible(){var s=Report();var w=s.DiagnosticSnapshot();var c=Assert.Single(WorkRelations.Known(w));Assert.Equal(Lord,c.Other);Assert.True(c.Local&&c.CanDiscussService);Assert.False(c.CanDiscussMilitary);Assert.Single(c.Proofs);Assert.Contains(w.WorkCycle!.Openings,o=>o.Message==c.Proofs[0].Basis);Assert.Empty(WorkRelations.Facts(w,s.PlayerControl,Lord));}
    [Fact]public void ActualPaymentCreatesDifferentReverseTrustFact(){var s=Report();var task=s.DiagnosticSnapshot().Tasks.Last();Assert.Equal(ResultCode.Accepted,s.CollectWorkPayment(new("payment:relation"),task.Id,s.PlayerControl,s.Revision).Code);var w=s.DiagnosticSnapshot();Assert.Equal("点検の履行を認めた",Assert.Single(WorkRelations.Facts(w,Lord,s.PlayerControl)).Kind);Assert.Equal("約束の点検報酬を実際に受領",Assert.Single(WorkRelations.Facts(w,s.PlayerControl,Lord)).Kind);Assert.Equal(2,WorkRelations.Known(w).Single().Proofs.Length);}
    [Fact]public void SameHouseDoesNotGiveThirdPartyTrust(){var s=Report();var w=s.DiagnosticSnapshot();Assert.Empty(WorkRelations.Facts(w,new("person:takeda-nobushige"),s.PlayerControl));Assert.Empty(WorkRelations.Facts(w,new("person:nobunaga"),s.PlayerControl));Assert.DoesNotContain(WorkRelations.Known(w),c=>c.Other!=Lord);}
    [Fact]public void DecliningWorkDoesNotCreatePositiveWorkTrust(){var s=Report(accept:false);Assert.Empty(WorkRelations.Facts(s.DiagnosticSnapshot(),Lord,s.PlayerControl));Assert.Empty(WorkRelations.Known(s.DiagnosticSnapshot()));}
    [Fact]public void ReopeningDoesNotDuplicateEvidence(){var s=Report();var w=s.DiagnosticSnapshot();var c=WorkRelations.Known(w);var id=new EntityId(c.Single().Proofs.Single().Basis);Assert.Equal(ResultCode.AlreadyAccepted,s.Open(s.PlayerControl,id,s.Revision).Code);Assert.Equal(ContractJson.Write(c),ContractJson.Write(WorkRelations.Known(s.DiagnosticSnapshot())));}
    [Fact]public void ProjectionsDoNotMutateWorldOrGrantRights(){var s=Report();var w=s.DiagnosticSnapshot();string hash=ContractJson.CanonicalHash(w);_ = WorkRelations.Known(w);_ = WorkRelations.Facts(w,Lord,s.PlayerControl);Assert.Equal(hash,ContractJson.CanonicalHash(w));Assert.DoesNotContain(w.Memberships,m=>m.Subject==s.PlayerControl);Assert.Null(w.NewMilitary);Assert.Empty(w.Units);}
    [Fact]public void RemoteContactRemainsRememberedButCannotOfferAudience(){var s=Report();Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:relation-trip","suwa"),s.Revision).Code);At(s,s.Seconds+3);var c=Assert.Single(WorkRelations.Known(s.DiagnosticSnapshot()));Assert.False(c.Local||c.CanDiscussService||c.CanDiscussMilitary);Assert.NotEmpty(c.Proofs);}
    [Fact]public void RelationshipLeadsThroughRealServiceToMilitaryConversation(){var s=Report();Assert.True(WorkRelations.Known(s.DiagnosticSnapshot()).Single().CanDiscussService);var id=Apply(s);Assert.Equal(ResultCode.Accepted,s.DecideService(new(new("request:relation-accept"),CareerAction.Accept,id),s.PlayerControl,s.Revision).Code);At(s,s.Seconds+2);Open(s);var w=s.DiagnosticSnapshot();var c=WorkRelations.Known(w).Single();Assert.False(c.CanDiscussService);Assert.True(c.CanDiscussMilitary);Assert.Equal(Lord,NewGameService.View(w).Principal);Assert.Null(w.NewMilitary);Assert.Empty(w.Units);}
    [Fact]public void PhysicalJoinAloneDoesNotRevealMilitaryAdvice(){var s=Report();var id=Apply(s);s.DecideService(new(new("request:relation-accept"),CareerAction.Accept,id),s.PlayerControl,s.Revision);At(s,s.Seconds+1);Assert.True(NewGameService.BoundAt(s.DiagnosticSnapshot(),Lord,s.Seconds,s.Revision));Assert.False(WorkRelations.Known(s.DiagnosticSnapshot()).Single().CanDiscussMilitary);At(s,s.Seconds+1);Open(s);Assert.True(WorkRelations.Known(s.DiagnosticSnapshot()).Single().CanDiscussMilitary);}
    [Fact]public void GenerationRestoreKeepsKnownAndDirectedEvidence(){var s=Report();s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"relations-"+Guid.NewGuid().ToString("N")),w.Definitions);store.Save(s,"manual",w.WorldId,new(0,1));var host=new WorldSessionHost(new(New()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("manual"),host.Current,host.Current.Revision));var x=host.Current.DiagnosticSnapshot();Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(x));Assert.Equal(ContractJson.Write(WorkRelations.Known(w)),ContractJson.Write(WorkRelations.Known(x)));Assert.Equal(ContractJson.Write(WorkRelations.Facts(w,Lord,s.PlayerControl)),ContractJson.Write(WorkRelations.Facts(x,Lord,s.PlayerControl)));}
    static readonly EntityId Job=new("job:relation-cargo");
    static WorldSession Cargo(){var s=new WorldSession(WorkFollowupTests.New());Assert.Equal(ResultCode.Accepted,s.RequestTransport(Job,s.Revision).Code);CargoStep(s,HandoverAction.Accept);CargoStep(s,HandoverAction.Collect);return s;}
    static void CargoStep(WorldSession s,HandoverAction action)=>Assert.Equal(ResultCode.Accepted,s.HandoverTransport(Job,TransportWorkTests.Input(s,action),s.Revision).Code);
    [Fact]public void CargoCancellationAndReturnDoNotInventTrustOrHostility(){var s=Cargo();CargoStep(s,HandoverAction.Cancel);CargoStep(s,HandoverAction.Return);var w=s.DiagnosticSnapshot();Assert.Empty(WorkRelations.Known(w));Assert.Empty(WorkRelations.Facts(w,Lord,s.PlayerControl));Assert.Empty(WorkRelations.Facts(w,s.PlayerControl,Lord));}
    [Fact]public void CargoReportAndPaymentHaveSeparateDirectionalBases(){var s=Cargo();TransportWorkTests.Travel(s,"suwa");CargoStep(s,HandoverAction.Deliver);Assert.Empty(WorkRelations.Facts(s.DiagnosticSnapshot(),Lord,s.PlayerControl));TransportWorkTests.Travel(s,"kofu");CargoStep(s,HandoverAction.Report);var w=s.DiagnosticSnapshot();Assert.Equal("運搬の履行を現地報告で確認",Assert.Single(WorkRelations.Facts(w,Lord,s.PlayerControl)).Kind);Assert.Empty(WorkRelations.Facts(w,s.PlayerControl,Lord));CargoStep(s,HandoverAction.Pay);w=s.DiagnosticSnapshot();Assert.Equal("約束の運賃を実際に受領",Assert.Single(WorkRelations.Facts(w,s.PlayerControl,Lord)).Kind);Assert.Equal(2,WorkRelations.Known(w).Single().Proofs.Length);}
    [Fact]public void LegacyProfilesKeepNoNewRelationshipProjection(){var w=WorkProgressionTests.New();Assert.Empty(WorkRelations.Known(w));Assert.Empty(WorkRelations.Facts(w,Lord,w.PlayerControl));Assert.Equal(ContractJson.Write(w),ContractJson.Write(ContractJson.Copy(w)));}
}
